static int failures;
#define CHECK(c, ...) do { if (!(c)) { failures++; printf("FAIL  " __VA_ARGS__); printf("\n"); } } while (0)

static void check_attr(const char *what, CRYPTCATATTRIBUTE *a, const WCHAR *tag, DWORD type, const WCHAR *value)
{
    CHECK(a != NULL, "%s: missing", what);
    if (!a) return;
    CHECK(a->cbStruct == sizeof(*a), "%s: cbStruct %lu", what, a->cbStruct);
    CHECK(!lstrcmpW(a->pwszReferenceTag, tag), "%s: tag %ls", what, a->pwszReferenceTag);
    CHECK(a->dwAttrTypeAndAction == type, "%s: type %#lx", what, a->dwAttrTypeAndAction);
    CHECK(a->cbValue == (lstrlenW(value) + 1) * sizeof(WCHAR) && !memcmp(a->pbValue, value, a->cbValue),
          "%s: value (%lu bytes)", what, a->cbValue);
}

int main(void)
{
    char path[MAX_PATH];
    WCHAR wpath[MAX_PATH];
    HANDLE file, cat;
    DWORD written;
    CRYPTCATMEMBER *m;
    CRYPTCATATTRIBUTE *a;

    GetTempPathA(sizeof(path), path);
    strcat(path, "sg-probe-cat.cat");
    MultiByteToWideChar(CP_ACP, 0, path, -1, wpath, MAX_PATH);
    file = CreateFileA(path, GENERIC_WRITE, 0, NULL, CREATE_ALWAYS, 0, NULL);
    WriteFile(file, test_cat, sizeof(test_cat), &written, NULL);
    CloseHandle(file);

    cat = CryptCATOpen(wpath, CRYPTCAT_OPEN_EXISTING, 0, 0, 0);
    CHECK(cat != INVALID_HANDLE_VALUE, "open %lu", GetLastError());
    if (cat == INVALID_HANDLE_VALUE) { DeleteFileA(path); printf("RESULT: FAIL\n"); return 1; }

    /* members come back in the reverse of the file order; the tag is the identifier when it is a string */
    m = CryptCATEnumerateMember(cat, NULL);
    CHECK(m && !lstrcmpW(m->pwszReferenceTag, L"hashme"), "first member tag %ls", m ? m->pwszReferenceTag : L"(none)");
    if (m)
    {
        a = CryptCATEnumerateAttr(cat, m, NULL);
        check_attr("member attr 1", a, L"mattr2", 0x10010002, L"mvalue2");
        a = CryptCATEnumerateAttr(cat, m, a);
        check_attr("member attr 2", a, L"mattr1", 0x10010001, L"mvalue1");
        a = CryptCATEnumerateAttr(cat, m, a);
        CHECK(a == NULL, "member has a third attribute");
        CHECK(GetLastError() == CRYPT_E_NOT_FOUND, "end of member attributes: %#lx", GetLastError());

        a = CryptCATGetAttrInfo(cat, m, (LPWSTR)L"mattr1");
        check_attr("get member attr", a, L"mattr1", 0x10010001, L"mvalue1");
        a = CryptCATGetAttrInfo(cat, m, (LPWSTR)L"nothere");
        CHECK(a == NULL && GetLastError() == CRYPT_E_NOT_FOUND, "missing member attr: %p %#lx", a, GetLastError());
    }
    m = CryptCATEnumerateMember(cat, m);
    CHECK(m && !lstrcmpW(m->pwszReferenceTag, L"404142434445464748494A4B4C4D4E4F50515253"),
          "second member tag %ls", m ? m->pwszReferenceTag : L"(none)");
    if (m)
    {
        a = CryptCATEnumerateAttr(cat, m, NULL);
        CHECK(a == NULL, "second member has attributes");
    }
    CHECK(CryptCATEnumerateMember(cat, m) == NULL, "a third member");

    /* catalog attributes: the reverse of the file order as well */
    a = CryptCATEnumerateCatAttr(cat, NULL);
    check_attr("cat attr 1", a, L"attr1", 0x10010001, L"value1");
    a = CryptCATEnumerateCatAttr(cat, a);
    check_attr("cat attr 2", a, L"attr2", 0x10010001, L"value2");
    a = CryptCATEnumerateCatAttr(cat, a);
    CHECK(a == NULL, "third catalog attribute");

    a = CryptCATGetCatAttrInfo(cat, (LPWSTR)L"attr2");
    check_attr("get cat attr", a, L"attr2", 0x10010001, L"value2");
    a = CryptCATGetCatAttrInfo(cat, (LPWSTR)L"attr3");
    CHECK(a == NULL && GetLastError() == CRYPT_E_NOT_FOUND, "missing cat attr: %p %#lx", a, GetLastError());

    m = CryptCATGetMemberInfo(cat, (LPWSTR)L"hashme");
    CHECK(m && !lstrcmpW(m->pwszReferenceTag, L"hashme"), "get member by tag");
    m = CryptCATGetMemberInfo(cat, (LPWSTR)L"nobody");
    CHECK(m == NULL && GetLastError() == CRYPT_E_NOT_FOUND, "missing member: %p %#lx", m, GetLastError());

    /* argument checks */
    CHECK(CryptCATEnumerateCatAttr(NULL, NULL) == NULL && GetLastError() == ERROR_INVALID_PARAMETER, "NULL catalog");
    CHECK(CryptCATGetCatAttrInfo(cat, NULL) == NULL, "NULL tag");

    CryptCATClose(cat);
    DeleteFileA(path);
    printf(failures ? "RESULT: FAIL\n" : "RESULT: PASS\n");
    return failures != 0;
}
